package com.shipmate.service;

import com.shipmate.model.App;
import org.springframework.stereotype.Service;

@Service
public class SpecGenerator {

    public String generate(App app, CostEstimator.Sizing sizing, double totalCost) {
        return """
                # Generated by Shipmate — do not edit unless you know why.
                name: %s
                repo: %s
                traffic:
                  rpm: %d
                  users: %d
                compute:
                  vcpu: %d
                  memoryGiB: %d
                  replicas: %d
                  maxReplicas: %d
                  instanceType: %s
                db:
                  engine: postgres
                  sizeGiB: %d
                  writeRpm: %d
                health: %s
                cost:
                  estimatedMonthly: %.2f
                """.formatted(
                app.getName(),
                app.getRepoUrl(),
                app.getTrafficRpm(),
                app.getTrafficUsers(),
                sizing.vcpu,
                sizing.memoryGiB,
                sizing.replicas,
                sizing.maxReplicas,
                sizing.instanceType,
                sizing.dbStorageGiB,
                sizing.dbWriteRpm,
                app.getHealthUrl(),
                totalCost);
    }
}
